import time

# Precomputed solutions for n=3..256
# Each entry is [x, y, z] or None
# Generated by the same divisor-based search, hardcoded for zero runtime cost

_SOLUTIONS = None

def _precompute():
    """Generate solutions once, cache in global."""
    global _SOLUTIONS
    if _SOLUTIONS is not None:
        return
    
    MAX_DENOM = 10**12
    solutions = {}
    
    for n in range(3, 257):
        found = None
        x_min = n // 4 + 1
        x_max = (3 * n) // 4
        
        for x in range(x_min, x_max + 1):
            a = 4 * x - n
            if a <= 0:
                continue
            b = n * x
            b2 = b * b
            
            # Find divisors of b2
            # Factor b
            temp = b
            factors = {}
            d = 2
            while d * d <= temp:
                while temp % d == 0:
                    factors[d] = factors.get(d, 0) + 1
                    temp //= d
                d += 1
            if temp > 1:
                factors[temp] = factors.get(temp, 0) + 1
            
            # Generate divisors of b2
            divs = [1]
            for p, e in factors.items():
                exp_b2 = 2 * e
                new_divs = []
                for dv in divs:
                    mult = 1
                    for _ in range(exp_b2 + 1):
                        new_divs.append(dv * mult)
                        mult *= p
                divs = new_divs
            
            for U in divs:
                if U >= b:
                    continue
                if (U + b) % a != 0:
                    continue
                y = (U + b) // a
                if y <= x:
                    continue
                V = b2 // U
                if (V + b) % a != 0:
                    continue
                z = (V + b) // a
                if z <= y:
                    continue
                if z > MAX_DENOM:
                    continue
                # Check distinctness
                if x == y or y == z or x == z:
                    continue
                found = [x, y, z]
                break
            if found:
                break
        
        solutions[n] = found
    
    _SOLUTIONS = solutions

def construct():
    _precompute()
    answers = []
    for n in range(3, 257):
        answers.append(_SOLUTIONS.get(n, None))
    return answers
